// src/pairing.ts
function normalizePairingCode(raw) {
  const digits = raw.replace(/\s+/g, "");
  if (!/^\d{8}$/.test(digits)) {
    return null;
  }
  return digits;
}
function mapExchangeError(status, body) {
  const code = body && typeof body === "object" && "code" in body ? String(body.code) : "";
  if (status === 400 || code === "invalid_code") {
    return "invalid_code";
  }
  if (status === 410 || code === "expired_code") {
    return "expired_code";
  }
  if (status === 0) {
    return "offline";
  }
  return "unknown";
}
function exchangeErrorMessage(kind) {
  if (kind === "invalid_code") {
    return PLUGIN_COPY.connectInvalidCode;
  }
  if (kind === "expired_code") {
    return PLUGIN_COPY.connectExpiredCode;
  }
  return PLUGIN_COPY.offline;
}
async function exchangePairingCode(fetchFn, baseUrl, code, vaultName) {
  const normalized = normalizePairingCode(code);
  if (!normalized) {
    return { ok: false, kind: "invalid_code", status: 400 };
  }
  let response;
  try {
    response = await fetchFn(pairingExchangeUrl(baseUrl), {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ code: normalized, vaultName })
    });
  } catch (e) {
    return { ok: false, kind: "offline", status: 0 };
  }
  let json = null;
  try {
    json = await response.json();
  } catch (e) {
    json = null;
  }
  if (!response.ok) {
    return {
      ok: false,
      kind: mapExchangeError(response.status, json),
      status: response.status
    };
  }
  if (!json || typeof json !== "object") {
    return { ok: false, kind: "unknown", status: response.status };
  }
  const record = json;
  if (typeof record.token !== "string" || typeof record.deviceId !== "string" || typeof record.accountLabel !== "string") {
    return { ok: false, kind: "unknown", status: response.status };
  }
  return {
    ok: true,
    token: record.token,
    deviceId: record.deviceId,
    accountLabel: record.accountLabel
  };
}

